50	// validate reports whether tok is still usable at time now.
51	func (a *Authenticator) validate(tok Token, now time.Time) error {
52		if tok.Revoked {
53			return errTokenRevoked
54		}
55		if tok.ExpiresAt.IsZero() {
56			return nil // non-expiring token
57		}
58		if !now.Before(tok.ExpiresAt) {
59			return errTokenExpired
60		}
61		return nil
62	}
